// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount * 2);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        bool okSecond;
        vm.prank(actor);
        try c.addToBalance{value: amount}() {
            okSecond = true;
        } catch {
            okSecond = false;
        }

        assertTrue(okSecond);
    }
}
